/**
 * The bone table shared by the inspect script (which writes
 * `cat-rig.gen.ts`) and the asset guard (which checks it against the GLB).
 */

import { normalizeBoneName } from '../../src/features/cat-room/lib/bone-names.ts'
import { nodeParents } from './glb.mjs'

export const RIG_FILE = 'src/features/cat-room/config/cat-rig.gen.ts'
export const SHIPPED_MODEL = 'public/models/cat.glb'
export const MODEL_URL = '/models/cat.glb'
/** Hex digits of the SHA-256 kept in the generated file. */
export const DIGEST_PREFIX = 16

/**
 * @typedef {{ key: string; parent: string | null }} RigBone
 * @typedef {{ bytes: number; sha256: string; bones: RigBone[] }} RigFacts
 */

/**
 * Bones of the first skin in skin order, keyed with {@link normalizeBoneName}.
 * Throws when two joints normalise to the same key.
 * @param {import('./glb.mjs').Glb} glb
 * @returns {RigBone[]}
 */
export function rigBones(glb) {
	const { json } = glb
	const skin = json.skins?.[0]
	if (!skin) throw new Error('The model has no skin')
	const parents = nodeParents(json)
	const keyOfNode = new Map()
	for (const node of skin.joints) {
		const key = normalizeBoneName(json.nodes[node].name ?? `node_${node}`)
		for (const [other, otherKey] of keyOfNode)
			if (otherKey === key)
				throw new Error(
					`Bone key collision: "${json.nodes[other].name}" and "${json.nodes[node].name}" both normalise to "${key}"`,
				)
		keyOfNode.set(node, key)
	}
	return skin.joints.map((node) => {
		const parent = parents.get(node)
		return {
			key: keyOfNode.get(node),
			parent:
				parent !== undefined ? (keyOfNode.get(parent) ?? null) : null,
		}
	})
}

/**
 * @param {import('./glb.mjs').Glb} glb
 * @returns {RigFacts}
 */
export function rigFacts(glb) {
	return {
		bytes: glb.byteLength,
		sha256: glb.sha256.slice(0, DIGEST_PREFIX),
		bones: rigBones(glb),
	}
}

/**
 * Source of `cat-rig.gen.ts`, already in Biome's style.
 * @param {RigFacts} facts
 */
export function renderRigModule(facts) {
	const bones = facts.bones
		.map(
			({ key, parent }) =>
				`\t{ key: '${key}', parent: ${parent === null ? 'null' : `'${parent}'`} },`,
		)
		.join('\n')
	return `// Generated by \`pnpm assets:inspect --write-rig\` from ${SHIPPED_MODEL}.
// Do not edit: \`pnpm assets:check\` fails when this file and the model disagree.

/** The shipped model: byte size for load progress, digest for the cache-busting URL. */
export const CAT_GLB = {
	url: '${MODEL_URL}',
	bytes: ${facts.bytes},
	sha256: '${facts.sha256}',
} as const

/** Bones in skin order: \`skeleton.bones[i]\` is \`CAT_RIG_BONES[i]\`. */
export const CAT_RIG_BONES = [
${bones}
] as const

export type CatBoneKey = (typeof CAT_RIG_BONES)[number]['key']
`
}
